package edu.studentportfolio.service;

import edu.studentportfolio.entity.*; import edu.studentportfolio.repository.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.LocalDate; import java.util.*;

@Service @Transactional
public class PortfolioService {
 private final UserRepository users; private final ProfileRepository profiles; private final SkillRepository skills; private final ProjectRepository projects; private final CertificationRepository certifications; private final CareerTaskRepository tasks;
 public PortfolioService(UserRepository u,ProfileRepository p,SkillRepository s,ProjectRepository pr,CertificationRepository c,CareerTaskRepository t){users=u;profiles=p;skills=s;projects=pr;certifications=c;tasks=t;}
 public User user(String email){return users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Student not found"));}
 private <T> T owned(Optional<T> item,java.util.function.Function<T,User> owner,String email){T x=item.orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found"));if(!owner.apply(x).getEmail().equals(email))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");return x;}
 public Map<String,Object> profile(String email){User u=user(email);StudentProfile p=profiles.findByUserEmail(email).orElseGet(()->{var n=new StudentProfile();n.setUser(u);return profiles.save(n);});var m=new LinkedHashMap<String,Object>();m.put("name",u.getName());m.put("email",u.getEmail());m.put("collegeName",u.getCollegeName());m.put("branch",u.getBranch());m.put("graduationYear",u.getGraduationYear());m.put("profile",p);return m;}
 public Map<String,Object> updateProfile(String email,Map<String,Object> x){User u=user(email);u.setName(str(x,"name",u.getName()));u.setCollegeName(str(x,"collegeName",u.getCollegeName()));u.setBranch(str(x,"branch",u.getBranch()));Object year=x.get("graduationYear");if(year instanceof Number n)u.setGraduationYear(n.intValue());users.save(u);StudentProfile p=profiles.findByUserEmail(email).orElseGet(()->{var n=new StudentProfile();n.setUser(u);return n;});p.setSummary(str(x,"summary",p.getSummary()));p.setPhotoUrl(str(x,"photoUrl",p.getPhotoUrl()));p.setDegree(str(x,"degree",p.getDegree()));p.setPhone(str(x,"phone",p.getPhone()));p.setLocation(str(x,"location",p.getLocation()));p.setLinkedinUrl(str(x,"linkedinUrl",p.getLinkedinUrl()));p.setGithubUrl(str(x,"githubUrl",p.getGithubUrl()));p.setCareerObjective(str(x,"careerObjective",p.getCareerObjective()));profiles.save(p);return profile(email);}
 private String str(Map<String,Object> m,String k,String old){Object v=m.get(k);return v==null?old:String.valueOf(v);}
 public List<Skill> skills(String e){return skills.findByUserEmail(e);} public Skill saveSkill(String e,Map<String,Object>x,Long id){Skill s=id==null?new Skill():owned(skills.findById(id),Skill::getUser,e);if(id==null)s.setUser(user(e));s.setName(req(x,"name"));s.setCategory(str(x,"category","Technical"));s.setProficiency(str(x,"proficiency","Beginner"));if(!List.of("Beginner","Intermediate","Advanced").contains(s.getProficiency()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid proficiency level");return skills.save(s);} public void deleteSkill(String e,Long id){skills.delete(owned(skills.findById(id),Skill::getUser,e));}
 public List<Project> projects(String e){return projects.findByUserEmail(e);} public Project saveProject(String e,Map<String,Object>x,Long id){Project p=id==null?new Project():owned(projects.findById(id),Project::getUser,e);if(id==null)p.setUser(user(e));p.setTitle(req(x,"title"));p.setDescription(str(x,"description",p.getDescription()));p.setTechnologies(str(x,"technologies",p.getTechnologies()));p.setGithubUrl(str(x,"githubUrl",p.getGithubUrl()));p.setLiveUrl(str(x,"liveUrl",p.getLiveUrl()));p.setStartDate(date(x,"startDate",p.getStartDate()));p.setCompletionDate(date(x,"completionDate",p.getCompletionDate()));return projects.save(p);} public void deleteProject(String e,Long id){projects.delete(owned(projects.findById(id),Project::getUser,e));}
 public List<Certification> certifications(String e){return certifications.findByUserEmail(e);} public Certification saveCertification(String e,Map<String,Object>x,Long id){Certification c=id==null?new Certification():owned(certifications.findById(id),Certification::getUser,e);if(id==null)c.setUser(user(e));c.setName(req(x,"name"));c.setOrganization(str(x,"organization",c.getOrganization()));c.setCredentialUrl(str(x,"credentialUrl",c.getCredentialUrl()));c.setIssueDate(date(x,"issueDate",c.getIssueDate()));return certifications.save(c);} public void deleteCertification(String e,Long id){certifications.delete(owned(certifications.findById(id),Certification::getUser,e));}
 public List<CareerTask> tasks(String e){return tasks.findByUserEmailOrderByDeadlineAsc(e);} public CareerTask saveTask(String e,Map<String,Object>x,Long id){CareerTask t=id==null?new CareerTask():owned(tasks.findById(id),CareerTask::getUser,e);if(id==null)t.setUser(user(e));t.setTitle(req(x,"title"));t.setDescription(str(x,"description",t.getDescription()));t.setCategory(str(x,"category","Other"));t.setStatus(str(x,"status",t.getStatus()));t.setPriority(str(x,"priority",t.getPriority()));if(!List.of("Not Started","In Progress","Completed").contains(t.getStatus()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");if(!List.of("Low","Medium","High").contains(t.getPriority()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid priority");t.setDeadline(date(x,"deadline",t.getDeadline()));return tasks.save(t);} public CareerTask taskStatus(String e,Long id,String status){CareerTask t=owned(tasks.findById(id),CareerTask::getUser,e);if(!List.of("Not Started","In Progress","Completed").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid status");t.setStatus(status);return tasks.save(t);} public void deleteTask(String e,Long id){tasks.delete(owned(tasks.findById(id),CareerTask::getUser,e));}
 private String req(Map<String,Object>x,String k){String v=str(x,k,null);if(v==null||v.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,k+" is required");return v;}
 private LocalDate date(Map<String,Object>x,String k,LocalDate old){if(!x.containsKey(k))return old;String v=str(x,k,null);return v==null||v.isBlank()?null:LocalDate.parse(v);}
 public Map<String,Object> dashboard(String e){var s=skills(e);var p=projects(e);var c=certifications(e);var t=tasks(e);long completed=t.stream().filter(x->"Completed".equals(x.getStatus())).count();long overdue=t.stream().filter(x->x.getDeadline()!=null&&x.getDeadline().isBefore(LocalDate.now())&& !"Completed".equals(x.getStatus())).count();return Map.of("student",profile(e),"skillsCount",s.size(),"projectsCount",p.size(),"certificationsCount",c.size(),"tasksCount",t.size(),"completedTasks",completed,"progress",t.isEmpty()?0:(int)(completed*100/t.size()),"overdueTasks",overdue,"upcomingTasks",t.stream().filter(x->x.getDeadline()!=null&& !x.getDeadline().isBefore(LocalDate.now())&& !"Completed".equals(x.getStatus())).limit(5).toList());}
}
